create or replace function public.guard_family_delete_with_transactions() returns trigger language plpgsql security definer set search_path='' as $$begin if exists(select 1 from public.transactions t where t.family_id=old.id and t.deleted_at is null) then raise exception 'FAMILY_HAS_ACTIVE_TRANSACTIONS';end if;return old;end$$;
create or replace function public.can_delete_family(p_family_id uuid) returns boolean language plpgsql stable security definer set search_path='' as $$begin if not public.is_family_owner(p_family_id) then raise exception 'FORBIDDEN';end if;return not exists(select 1 from public.transactions t where t.family_id=p_family_id and t.deleted_at is null);end$$;
create or replace function public.delete_empty_family(p_family_id uuid) returns boolean language plpgsql security definer set search_path='' as $$declare locked_family uuid;begin if not public.is_family_owner(p_family_id) then raise exception 'FORBIDDEN';end if;select id into locked_family from public.families where id=p_family_id for update;if not found then raise exception 'FAMILY_NOT_FOUND';end if;if exists(select 1 from public.transactions t where t.family_id=p_family_id and t.deleted_at is null) then raise exception 'FAMILY_HAS_ACTIVE_TRANSACTIONS';end if;delete from public.transactions t where t.family_id=p_family_id and t.deleted_at is not null;delete from public.families f where f.id=p_family_id;return found;end$$;
create or replace function public.guard_catalog_delete_in_use() returns trigger language plpgsql security definer set search_path='' as $$begin if tg_table_name='purposes' and exists(select 1 from public.transactions t where t.purpose_id=old.id and t.deleted_at is null) then raise exception 'CATALOG_IN_USE';end if;if tg_table_name='expense_types' and exists(select 1 from public.transactions t where t.expense_type_id=old.id and t.deleted_at is null) then raise exception 'CATALOG_IN_USE';end if;if tg_table_name='payment_methods' and exists(select 1 from public.transactions t where t.payment_method_id=old.id and t.deleted_at is null) then raise exception 'CATALOG_IN_USE';end if;return old;end$$;
create or replace function public.delete_catalog_item(p_family_id uuid,p_kind text,p_item_id uuid) returns boolean language plpgsql security definer set search_path='' as $$declare item_exists boolean:=false;active_tx boolean:=false;any_tx boolean:=false;begin if not public.is_family_owner(p_family_id) then raise exception 'FORBIDDEN';end if;if p_kind='purpose' then select exists(select 1 from public.purposes p where p.id=p_item_id and p.family_id=p_family_id) into item_exists;select exists(select 1 from public.transactions t where t.purpose_id=p_item_id and t.deleted_at is null),exists(select 1 from public.transactions t where t.purpose_id=p_item_id) into active_tx,any_tx;if active_tx then raise exception 'CATALOG_IN_USE';end if;delete from public.budgets b where b.family_id=p_family_id and b.purpose_id=p_item_id;delete from public.purpose_expense_type_suggestions s where s.purpose_id=p_item_id;if any_tx then update public.purposes set active=false where id=p_item_id and family_id=p_family_id;else delete from public.purposes where id=p_item_id and family_id=p_family_id;end if;elsif p_kind='expenseType' then select exists(select 1 from public.expense_types e where e.id=p_item_id and e.family_id=p_family_id) into item_exists;select exists(select 1 from public.transactions t where t.expense_type_id=p_item_id and t.deleted_at is null),exists(select 1 from public.transactions t where t.expense_type_id=p_item_id) into active_tx,any_tx;if active_tx then raise exception 'CATALOG_IN_USE';end if;delete from public.purpose_expense_type_suggestions s where s.expense_type_id=p_item_id;if any_tx then update public.expense_types set active=false where id=p_item_id and family_id=p_family_id;else delete from public.expense_types where id=p_item_id and family_id=p_family_id;end if;elsif p_kind='paymentMethod' then select exists(select 1 from public.payment_methods pm where pm.id=p_item_id and pm.family_id=p_family_id) into item_exists;select exists(select 1 from public.transactions t where t.payment_method_id=p_item_id and t.deleted_at is null),exists(select 1 from public.transactions t where t.payment_method_id=p_item_id) into active_tx,any_tx;if active_tx then raise exception 'CATALOG_IN_USE';end if;if any_tx then update public.payment_methods set active=false where id=p_item_id and family_id=p_family_id;else delete from public.payment_methods where id=p_item_id and family_id=p_family_id;end if;else raise exception 'INVALID_CATALOG_KIND';end if;return item_exists;end$$;
